dataset.schema:
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, jurisdiction TEXT NOT NULL, risk_rating TEXT NOT NULL CHECK (risk_rating IN ('low','medium','high')), is_pep INTEGER NOT NULL DEFAULT 0);
CREATE TABLE accounts (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), account_type TEXT NOT NULL CHECK (account_type IN ('checking','savings','business','foreign')));
CREATE TABLE transactions (id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), txn_type TEXT NOT NULL CHECK (txn_type IN ('cash_deposit','wire_in','wire_out','ach','transfer')), amount NUMERIC NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', txn_date TEXT NOT NULL);
